{
	while (start != end)
		std::cout << *start++ << '\n';
}

inline void print(const int a[], size_t size)
{
	for (size_t i = 0; i != size; ++i)
		std::cout << a[i] << '\n';
}

inline void print(const int (&a)[2])
{
	for (auto element : a)
		std::cout << element << '\n';
